let cepLookupVersion=0;
async function ewLookupCep(){
  const input=document.getElementById('ewCep');if(!input)return;
  const cep=String(input.value||'').replace(/\D/g,'');
  const status=()=>document.getElementById('ewCepStatus');
  if(cep.length!==8){if(status())status().textContent='Informe um CEP válido com 8 números.';return;}
  const version=++cepLookupVersion;state.cep=cep.slice(0,5)+'-'+cep.slice(5);
  if(status())status().textContent='Buscando o endereço…';
  const controllers=[];
  const lookup=async(url,convert)=>{const controller=new AbortController();controllers.push(controller);const timer=setTimeout(()=>controller.abort(),6500);try{const r=await fetch(url,{signal:controller.signal,headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw new Error('Consulta indisponível');const raw=await r.json();if(raw.erro)throw new Error('CEP não encontrado');const data=convert(raw);if(!data.city||!data.state)throw new Error('CEP não encontrado');return data;}finally{clearTimeout(timer)}};
  try{
    const address=await Promise.any([
      lookup('https://viacep.com.br/ws/'+cep+'/json/',d=>({street:d.logradouro,neighborhood:d.bairro,city:d.localidade,state:d.uf})),
      lookup('https://brasilapi.com.br/api/cep/v1/'+cep,d=>({street:d.street,neighborhood:d.neighborhood,city:d.city,state:d.state}))
    ]);
    if(version!==cepLookupVersion||String(state.cep||'').replace(/\D/g,'')!==cep)return;
    state.location=[address.street,address.neighborhood,address.city,address.state].filter(Boolean).join(', ');
    state.regionApprox=[address.neighborhood,address.city,address.state].filter(Boolean).join(', ');
    const locationInput=document.querySelector('[data-input="location"]');
    if(locationInput){locationInput.value=state.location;locationInput.dispatchEvent(new Event('input',{bubbles:true}));}
    if(status())status().textContent='Endereço localizado. Complete o número e o complemento. A busca por CEP não depende do GPS.';
  }catch(error){if(version===cepLookupVersion&&status())status().textContent='Não foi possível consultar este CEP agora. Confira os 8 números ou preencha o endereço manualmente.';}
  finally{controllers.forEach(c=>c.abort());}
}

