let gpsRequestInFlight=null;
async function gpsReadable(){
  if(gpsRequestInFlight)return gpsRequestInFlight;
  if(!navigator.geolocation){v56Toast('Este navegador não oferece localização. Você pode usar o CEP sem permitir GPS.');return;}
  const button=document.querySelector('[data-act="gps"]');if(button){button.disabled=true;button.textContent='Localizando…';}
  gpsRequestInFlight=(async()=>{
    const locate=options=>new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,options));
    let position;
    try{position=await locate({enableHighAccuracy:false,timeout:6000,maximumAge:180000});}
    catch(error){if(error.code===1)throw error;position=await locate({enableHighAccuracy:true,timeout:10000,maximumAge:60000});}
    const latitude=Number(position.coords.latitude),longitude=Number(position.coords.longitude);
    state.gpsLocation={latitude,longitude,accuracy:Number(position.coords.accuracy)||null};
    const reverse=async(url,convert)=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6000);try{const response=await fetch(url,{signal:controller.signal,headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Endereço indisponível');const data=convert(await response.json());if(!data.label)throw new Error('Endereço indisponível');return data;}finally{clearTimeout(timer)}};
    let address;
    try{address=await Promise.any([
      reverse('https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat='+encodeURIComponent(latitude)+'&lon='+encodeURIComponent(longitude)+'&zoom=18&addressdetails=1',data=>{const a=data.address||{};return {label:[a.road,a.suburb||a.neighbourhood,a.city||a.town||a.village,a.state,a.postcode].filter(Boolean).join(', '),cep:a.postcode};}),
      reverse('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+encodeURIComponent(latitude)+'&longitude='+encodeURIComponent(longitude)+'&localityLanguage=pt',data=>({label:[data.locality||data.city,data.principalSubdivision,data.countryName].filter(Boolean).join(', '),cep:data.postcode}))
    ]);}catch(error){v56Toast('O GPS foi obtido, mas a busca de endereço está indisponível. Informe o CEP para completar o endereço; a localização foi preservada.');return;}
    state.location=address.label;
    const digits=String(address.cep||'').replace(/\D/g,'');if(digits.length===8){state.cep=digits.slice(0,5)+'-'+digits.slice(5);const cep=document.getElementById('ewCep');if(cep)cep.value=state.cep;}
    const input=document.querySelector('[data-input="location"]');if(input){input.value=address.label;input.dispatchEvent(new Event('input',{bubbles:true}));}
    v56Toast('Localização encontrada. Confira o endereço e complete o número.');
  })().catch(error=>v56Toast(error?.code===1?'A permissão de GPS foi negada. Você pode localizar o endereço pelo CEP.':'O aparelho não conseguiu obter o GPS agora. A busca por CEP continua disponível.')).finally(()=>{gpsRequestInFlight=null;const current=document.querySelector('[data-act="gps"]');if(current){current.disabled=false;current.textContent='◎ Usar GPS';}});
  return gpsRequestInFlight;
}

