function addProfessionalHistory(){
  if(state.page!=='completedreviews'||!state.supabaseUser)return;
  const panel=document.querySelector('#app .panel');if(!panel)return;
  const userId=String(state.supabaseUser.id),pro=state.currentRole==='Profissional';
  const completed=(state.orders||[]).filter(order=>{
    const own=pro?String(order.professional_id||order.selectedProposal?.professional_id||'')===userId:String(order.client_id)===userId;
    return own&&!!window.fechouIsServiceCompleted?.(order);
  });
  panel.classList.add('v63-history');
  panel.innerHTML='<div class="section-head"><h2>Histórico de serviços</h2><span class="pill">'+completed.length+' concluído(s)</span></div>'+(completed.length?'<div class="v63-history-track">'+completed.map(order=>{
    const review=order.review||{},rating=Number(review.rating||0);
    return '<article class="v63-history-card"><b>'+esc(order.service||order.title||'Serviço')+'</b><span class="muted">'+esc(order.category||'')+' · '+moneyBRL(order.total||0)+'</span><strong>'+(rating>0?rating.toLocaleString('pt-BR',{maximumFractionDigits:1})+' ★':'Aguardando avaliação')+'</strong>'+(review.comment?'<p>'+esc(review.comment)+'</p>':'')+'<button class="btn secondary small" type="button" data-act="openarchive:'+esc(order.id)+'">Ver registro completo</button></article>';
  }).join('')+'</div>':'<div class="empty">Nenhum serviço concluído confirmado foi encontrado nesta conta.</div>');
}

