function requestMediaList(order){
 const all=[...(Array.isArray(order?.photos)?order.photos:[]),...(Array.isArray(order?.videos)?order.videos:[])];
 const seen=new Set();
 return all.map(item=>typeof item==='string'?{url:item}:item).filter(item=>{
  if(!item||seen.has(item.path||item.url))return false;
  try{const raw=item.url||item.signedUrl;if(!raw)return false;const url=new URL(raw,location.origin);if(!/^https?:$/.test(url.protocol)||url.username||url.password)return false;seen.add(item.path||url.href);return true;}catch(_){return false;}
 });
}
function renderRequestMedia(order){
 return requestMediaList(order).map((item,index)=>{
  const mime=String(item.mime||item.mime_type||item.type||'').toLowerCase();
  const url=esc(item.url||item.signedUrl),name=esc(item.name||('Anexo '+(index+1)));
  const kind=mime.startsWith('audio/')||/\.(m4a|mp3|wav|ogg)(\?|$)/i.test(item.path||item.url)?'audio':mime.startsWith('video/')||/\.(mp4|mov|webm)(\?|$)/i.test(item.path||item.url)?'video':'image';
  const open=`data-request-media-open="${index}" data-order-id="${esc(order.id)}"`;
  if(kind==='audio')return `<figure class="r17-photo r18-request-audio"><audio controls preload="metadata" src="${url}" aria-label="${name}"></audio><button type="button" class="btn secondary small" ${open}>Abrir áudio</button><figcaption>${name}</figcaption></figure>`;
  return `<figure class="r17-photo"><button type="button" class="r18-request-media-open" ${open} aria-label="Ampliar ${kind==='video'?'vídeo':'foto'} ${index+1}">${kind==='video'?`<video playsinline muted preload="metadata" src="${url}" aria-label="${name}"></video><span>▶ Abrir vídeo</span>`:`<img class="photo" src="${url}" alt="Foto do local ${index+1}" loading="lazy">`}</button><figcaption>${name}</figcaption></figure>`;
 }).join('');
}
function openRequestMedia(order,index=0){
