 document.getElementById('fechou-request-gallery')?.remove();
 const previous=document.activeElement,overlay=document.createElement('div');overlay.id='fechou-request-gallery';overlay.className='r18-request-gallery';
 overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Anexos da solicitação');
 overlay.innerHTML='<section><header><b>Anexos do pedido</b><button type="button" data-media-close aria-label="Fechar anexos">×</button></header><div class="r18-media-stage"></div><footer><button type="button" data-media-prev aria-label="Anexo anterior">‹</button><span role="status"></span><button type="button" data-media-next aria-label="Próximo anexo">›</button></footer></section>';
 document.body.append(overlay);
 const close=()=>{overlay.querySelectorAll('video,audio').forEach(el=>el.pause());overlay.remove();if(previous?.isConnected)previous.focus();};
 const show=()=>{index=(index+items.length)%items.length;const item=items[index],mime=String(item.mime||item.mime_type||item.type||'').toLowerCase(),url=item.url||item.signedUrl;
  const stage=overlay.querySelector('.r18-media-stage');stage.querySelectorAll('video,audio').forEach(el=>el.pause());
  const kind=mime.startsWith('audio/')||/\.(m4a|mp3|wav|ogg)(\?|$)/i.test(item.path||url)?'audio':mime.startsWith('video/')||/\.(mp4|mov|webm)(\?|$)/i.test(item.path||url)?'video':'img';
  stage.replaceChildren();const media=document.createElement(kind);media.src=url;
  if(kind==='img')media.alt=item.name||'Foto do pedido';else{media.controls=true;media.preload='metadata';media.setAttribute('playsinline','');media.setAttribute('controlslist','nodownload noplaybackrate noremoteplayback');}
  stage.append(media);overlay.querySelector('[role=status]').textContent=(index+1)+' de '+items.length;
  overlay.querySelectorAll('[data-media-prev],[data-media-next]').forEach(b=>b.disabled=items.length===1);
 };
 overlay.querySelector('[data-media-close]').onclick=close;
 overlay.querySelector('[data-media-prev]').onclick=()=>{index--;show()};overlay.querySelector('[data-media-next]').onclick=()=>{index++;show()};
 overlay.addEventListener('click',event=>{if(event.target===overlay)close()});
 overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();if(event.key==='ArrowLeft'){index--;show()}if(event.key==='ArrowRight'){index++;show()}if(event.key==='Tab'){const buttons=[...overlay.querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
 show();overlay.querySelector('[data-media-close]').focus();
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-request-media-open]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const order=(state.orders||[]).find(o=>String(o.id)===button.dataset.orderId);if(order)openRequestMedia(order,Number(button.dataset.requestMediaOpen)||0);},true);

