async function uploadRequestMedia(files){
 const normalized=files.map(f=>({name:f.name||'arquivo',size:f.size,mime:({'audio/x-m4a':'audio/mp4','audio/m4a':'audio/mp4','audio/x-wav':'audio/wav'})[String(f.type||'').split(';')[0].toLowerCase()]||String(f.type||'').split(';')[0].toLowerCase()}));
 if(files.length>150||files.reduce((sum,f)=>sum+f.size,0)>300*1024*1024)throw new Error('Envie até 150 arquivos, somando no máximo 300 MB. O formulário foi preservado.');
 if(files.some(f=>!f.size||f.size>50*1024*1024))throw new Error('Cada arquivo deve ter até 50 MB. O formulário foi preservado.');
 if(!files.length)return [];
 const c=db()||await window.fechouEnsureSupabaseClient?.();
 if(!c?.storage)throw new Error('O serviço de anexos está indisponível. O formulário foi preservado.');
 const prepared=await api('orders/media-upload-urls',{upload_session:draftKey,media:normalized});
 if(!Array.isArray(prepared.uploads)||prepared.uploads.length!==files.length)throw new Error('Não foi possível preparar todos os anexos.');
 const stored=[];
 for(let i=0;i<files.length;i++){
  const upload=prepared.uploads[i];
  if(!String(upload.path||'').startsWith(uid()+'/request/'+draftKey+'/'))throw new Error('Destino de anexo inválido.');
  note('Enviando anexo '+(i+1)+' de '+files.length+'…');
  const {error}=await c.storage.from('eworkers-chat').uploadToSignedUrl(upload.path,upload.token,files[i],{contentType:upload.mime,cacheControl:'3600'});
  if(error)throw new Error('O anexo '+(i+1)+' não foi enviado. Confira a conexão; o formulário foi preservado.');
  stored.push({path:upload.path,name:upload.name,mime:upload.mime,size:upload.size});
 }
 return stored;
}

